function的实现，其主要使用的是type-erasure技术
这种type-erasure技术，本质上在调用相应的函数时，绕过了编译器对参数的类型检查。
一个简单的实现如下
#include 
#include 

template 
class function;

template 
class function
{
    // function pointer types for the type-erasure behaviors
    // all these char* parameters are actually casted from some functor type
    typedef R (*invoke_fn_t)(char*, const Args&...);
    typedef void (*construct_fn_t)(char*, char*);
    typedef void (*destroy_fn_t)(char*);

    // type-aware generic functions for invoking
    // the specialization of these functions won't be capable with the above function pointer types, so we need some cast between the Functor and  char*
    template 
    static R invoke_fn(Functor* fn, const Args&... args)
    {
        return (*fn)(args...);
    }

    template 
    static void construct_fn(Functor* construct_dst, Functor* construct_src)
    {
        // the functor type must be copy-constructible
        //lambda也是可以拷贝构造的~，只是lambda不能赋值而已
        new (construct_dst) Functor(*construct_src);
    }

    template 
    static void destroy_fn(Functor* f)
    {
        f->~Functor();
    }

    // these pointers are storing behaviors
    invoke_fn_t invoke_f;
    construct_fn_t construct_f;
    destroy_fn_t destroy_f;

    // erase the type of any functor and store it into a char*
    // so the storage size should be obtained as well
    //注意这里是char[], 表示一个char数组，而不能是char*。如果是char*, 则 std::unique_ptr::pointer 为char**
    std::unique_ptr data_ptr;
    size_t data_size;
public:
    function()
        : invoke_f(nullptr)
        , construct_f(nullptr)
        , destroy_f(nullptr)
        , data_ptr(nullptr)
        , data_size(0)
    {}

    // construct from any functor type
    template 
    function(Functor f)
        // specialize functions and erase their type info by casting
        : invoke_f(reinterpret_cast(invoke_fn))
        , construct_f(reinterpret_cast(construct_fn))
        , destroy_f(reinterpret_cast(destroy_fn))
        , data_ptr(new char[sizeof(Functor)])
        , data_size(sizeof(Functor))
    {
        // copy the functor to internal storage
        this->construct_f(this->data_ptr.get(), reinterpret_cast(&f));
    }

    // copy constructor
    function(function const& rhs)
        : invoke_f(rhs.invoke_f)
        , construct_f(rhs.construct_f)
        , destroy_f(rhs.destroy_f)
        , data_size(rhs.data_size)
    {
        //非null function
        if (this->invoke_f) {
            // when the source is not a null function, copy its internal functor
            this->data_ptr.reset(new char[this->data_size]);
            this->construct_f(this->data_ptr.get(), rhs.data_ptr.get());
        }
    }

    ~function()
    {
        if (data_ptr != nullptr) {
            this->destroy_f(this->data_ptr.get());
        }
    }

    template
    R operator()(CallArgs&&... args)
    {
        return this->invoke_f(this->data_ptr.get(), std::forward(args)...);
    }
};

