以下程序中迭代器的使用有什么错误或不合理之处
int main()
{
vector e;
copy( istream_iterator( cin ), istream_iterator(), back_inserter( e ) );
vector::iterator first = find( e.begin(), e.end(), "01/01/95" );
vector::iterator last = find( e.begin(), e.end(), "12/31/95" );
*last = "12/30/95";
copy( first, last, ostream_iterator( cout, "\n" ) );
e.insert( --e.end(), TodaysDate() );
copy( first, last, ostream_iterator( cout, "\n" ) );
}

vector::iterator first = find( e.begin(), e.end(), "01/01/95" );
vector::iterator last = find( e.begin(), e.end(), "12/31/95" );
*last = "12/30/95";

直接对last解引用是不合理的，因为last可能指向e.end();
紧随其后的copy语句
copy( first, last, ostream_iterator( cout, "\n" ) );

