      address(const_reference __x) const noexcept
      { return std::__addressof(__x); }



      // NB: __n is permitted to be 0.  The C++ standard says nothing
      // about what the return value is when __n == 0.
      _Tp* allocate(size_type __n, const void* = static_cast(0))
      {
        static_assert(sizeof(_Tp) != 0, "cannot allocate incomplete types");


           if (__builtin_expect(__n > this->_M_max_size(), false))
           {
             if (__n > (std::size_t(-1) / sizeof(_Tp)))
               std::__throw_bad_array_new_length();
             std::__throw_bad_alloc();
           }
        //....
          return static_cast(::operator new(__n * sizeof(_Tp)));
      }

      // __p is not permitted to be a null pointer.
      // __attribute__ ((__unused__)) 表示__n 这个参数可能不会使用，编译器不需要给出warning
      void deallocate(_Tp* __p, size_type __n __attribute__ ((__unused__)))
      {
       #if __cpp_sized_deallocation
       # define _GLIBCXX_SIZED_DEALLOC(p, n) (p), (n) * sizeof(_Tp)
       #else
       # define _GLIBCXX_SIZED_DEALLOC(p, n) (p)
       #endif
       ::operator delete(_GLIBCXX_SIZED_DEALLOC(__p, __n));
      }

      //这里为什么要用placement new， 而不是直接`__p->_Up(std::forward(__args)...)`
      //因为构造函数不可以这样调用，在inside c++ object model 中有说明
      template
         void  construct(_Up* __p, _Args&&... __args)
      noexcept(std::is_nothrow_constructible::value)
         { ::new((void *)__p) _Up(std::forward(__args)...); }



      template
         void destroy(_Up* __p)
         noexcept(std::is_nothrow_destructible::value)
         { __p->~_Up(); }






    private:
      size_type _M_max_size() const 
      {
        return std::size_t(-1) / sizeof(_Tp);
      }



    };

以上实现的代码删减了很多。STL中不同版本的代码都堆在一起，用宏区分，有的版本多了接口，有的接口不同版本实现不一样，有的版本增加了新特性。本笔记中只提供大概实现。
另外，代码中的很多constexpr, noexcept等会随机省去。
如果一个函数在末尾添加了noexcept,或者 noexcept(true),表明该函数不会抛出异常。编译器对此类函数省去了异常处理的支持，万一运行时还是抛出异常了，直接terminate. 默认情况下，或者加了noexcept(false)声明的函数，都是表明可能抛出异常。编译器对此类的函数都需要做异常处理的支持。
如果一个函数之前添加了constexpr keyword,表明该函数是compile-time constant/expression，可以直接在编译期求值。
所有类型的allocator,都需要提供allocate,deallocate,construct,destroy四个方法。
G2.9版本的stl中，默认的分配器是alloc,alloc使用链表缓存分配的内存块。

G4.9中的__gnu_cxx::__pool_alloc就是G2.9中的alloc,那我们看下__gnu_cxx::__pool_alloc的实现
  template
    class __pool_alloc : private __pool_alloc_base
    {
        //...
    public:
