  template
    _Tp* __pool_alloc::allocate(size_type __n, const void*)
    {
        pointer __ret = 0;
        if (__builtin_expect(__n != 0, true))
          {
            //...

              const size_t __bytes = __n * sizeof(_Tp);          
              if (__bytes > size_t(_S_max_bytes) || _S_force_new > 0)
                  __ret = static_cast(::operator new(__bytes));
              else {
              //指针的指针，_Obj* volatile的指针 
                 _Obj* volatile* __free_list = _M_get_free_list(__bytes);

                 __scoped_lock sentry(_M_get_mutex());
                 _Obj* __restrict__ __result = *__free_list;
                 if (__builtin_expect(__result == 0, 0))
                     __ret = static_cast(_M_refill(_M_round_up(__bytes)));
                 else {
                     *__free_list = __result->_M_free_list_link;
                     __ret = reinterpret_cast(__result);
                   }
                 if (__ret == 0)
                     std::__throw_bad_alloc();
              }
          }
        return __ret;
    }

  template
    void __pool_alloc::deallocate(pointer __p, size_type __n)
    {
        if (__builtin_expect(__n != 0 && __p != 0, true))
       {
            const size_t __bytes = __n * sizeof(_Tp);
            if (__bytes > static_cast(_S_max_bytes) || _S_force_new > 0)
                ::operator delete(__p);
            else
            {
               _Obj* volatile* __free_list = _M_get_free_list(__bytes);
               _Obj* __q = reinterpret_cast(__p);

               __scoped_lock sentry(_M_get_mutex());
               __q ->_M_free_list_link = *__free_list;
               *__free_list = __q;
            }
       }
    }



