容器分为序列式容器和关联式容器

序列式容器：array,vector, list, forward_list, deque
关联式容器：map, set,multimap,multiset， unordered_map,unordered_set,unordered_multimap,unordered_multiset

list实现 G2.8

template 
struct __list_node {
  typedef void* void_pointer;
  void_pointer next; //为什么要转换成void*的指针，不知道
  void_pointer prev;
  T data;
};

/*
可以直接写成

template 
struct list_node {
  list_node* next; 
  list_node* prev;
  T data;
};
*/


//list iterator是 bidirectional_iterator, 
//需要实现的操作有 ++，--， 
//除此之外有指针操作，解引用操作，比较操作
template
struct __list_iterator {
  typedef __list_iterator             iterator;
  typedef __list_iterator const_iterator;
  typedef __list_iterator           self;

  typedef bidirectional_iterator_tag iterator_category;
  typedef T value_type;
  typedef Ptr pointer;
  typedef Ref reference;
  typedef __list_node* link_type;
  typedef size_t size_type;
  typedef ptrdiff_t difference_type;

  link_type node;

  __list_iterator(link_type x) : node(x) {}
  __list_iterator() {}
  __list_iterator(const iterator& x) : node(x.node) {}

  bool operator==(const self& x) const { return node == x.node; }
  bool operator!=(const self& x) const { return node != x.node; }
  reference operator*() const { return (*node).data; }

  pointer operator->() const { return &(operator*()); }

  self& operator++() { 
    node = (link_type)((*node).next);
    return *this;
  }
  self operator++(int) { 
    self tmp = *this;
    ++*this;
    return tmp;
  }
  self& operator--() { 
    node = (link_type)((*node).prev);
    return *this;
  }
  self operator--(int) { 
    self tmp = *this;
    --*this;
    return tmp;
  }
};

template 
class list {
protected:
  typedef void* void_pointer;
  typedef __list_node list_node;
  typedef simple_alloc list_node_allocator;
public:      
  typedef T value_type;
  typedef value_type* pointer;
  typedef const value_type* const_pointer;
  typedef value_type& reference;
  typedef const value_type& const_reference;
  typedef list_node* link_type;
  typedef size_t size_type;
  typedef ptrdiff_t difference_type;

public:
  typedef __list_iterator             iterator;
  typedef __list_iterator const_iterator;
  typedef reverse_iterator const_reverse_iterator;
  typedef reverse_iterator reverse_iterator;


protected:
  link_type get_node() { return list_node_allocator::allocate(); }
  void put_node(link_type p) { list_node_allocator::deallocate(p); }

  link_type create_node(const T& x) {
    link_type p = get_node();
    __STL_TRY {
      construct(&p->data, x); //调用placement new,兼容POD类型
    }
    __STL_UNWIND(put_node(p));
    return p;
  }
  void destroy_node(link_type p) {
    destroy(&p->data); //析构函数可以直接调用，兼容POD类型
    put_node(p);
  }

protected:
  void empty_initialize() { 
    node = get_node();
    node->next = node;
    node->prev = node;
  }

  //list的初始化，最终都是调用的insert,一个一个node的create,链接。
  void fill_initialize(size_type n, const T& value) {
    empty_initialize();
    __STL_TRY {
      insert(begin(), n, value);
    }
    __STL_UNWIND(clear(); put_node(node));
  }

  template 
  void range_initialize(InputIterator first, InputIterator last) {
    empty_initialize();
    __STL_TRY {
      insert(begin(), first, last);
    }
    __STL_UNWIND(clear(); put_node(node));
  }




protected:
  link_type node;

public:
  list() { empty_initialize(); }
  list(size_type n, const T& value) { fill_initialize(n, value); }
  list(int n, const T& value) { fill_initialize(n, value); }
  list(long n, const T& value) { fill_initialize(n, value); }
  explicit list(size_type n) { fill_initialize(n, T()); }

  template 
  list(InputIterator first, InputIterator last) {
    range_initialize(first, last);
  }


  list(const list& x) {
    range_initialize(x.begin(), x.end());
  }
  ~list() {
    clear();
    put_node(node);
  }
  list& operator=(const list& x);



  iterator begin() { return (link_type)((*node).next); }
  const_iterator begin() const { return (link_type)((*node).next); }
  iterator end() { return node; }
  const_iterator end() const { return node; }
  reverse_iterator rbegin() { return reverse_iterator(end()); }
  const_reverse_iterator rbegin() const { 
    return const_reverse_iterator(end()); 
  }
  reverse_iterator rend() { return reverse_iterator(begin()); }
  const_reverse_iterator rend() const { 
    return const_reverse_iterator(begin());
  } 


  bool empty() const { return node->next == node; }
  size_type size() const {
    size_type result = 0;
