    distance(begin(), end(), result);
    return result;
  }
  size_type max_size() const { return size_type(-1); }
  reference front() { return *begin(); }
  const_reference front() const { return *begin(); }
  reference back() { return *(--end()); }
  const_reference back() const { return *(--end()); }
  void swap(list& x) { __STD::swap(node, x.node); }

//list的操作有insert,erase, push_front, push_back，都是操作的指针
//insert有单独插入，批量插入。批量插入其实现也是调用的单独插入
  iterator insert(iterator position, const T& x) {
    link_type tmp = create_node(x);
    tmp->next = position.node;
    tmp->prev = position.node->prev;
    (link_type(position.node->prev))->next = tmp;
    position.node->prev = tmp;
    return tmp;
  }
  iterator insert(iterator position) { return insert(position, T()); }

  template 
  void insert(iterator position, InputIterator first, InputIterator last);

  void insert(iterator pos, size_type n, const T& x);

  void insert(iterator pos, int n, const T& x) {
    insert(pos, (size_type)n, x);
  }
  void insert(iterator pos, long n, const T& x) {
    insert(pos, (size_type)n, x);
  }


  void push_front(const T& x) { insert(begin(), x); }
  void push_back(const T& x) { insert(end(), x); }


  iterator erase(iterator position) {
    link_type next_node = link_type(position.node->next);
    link_type prev_node = link_type(position.node->prev);
    prev_node->next = next_node;
    next_node->prev = prev_node;
    destroy_node(position.node);
    return iterator(next_node);
  }
  iterator erase(iterator first, iterator last);

  void resize(size_type new_size, const T& x);
  void resize(size_type new_size) { resize(new_size, T()); }


  void clear();

  void pop_front() { erase(begin()); }
  void pop_back() { 
    //注意不能直接erase(--end())哦
    iterator tmp = end();
    erase(--tmp);
  }


protected:
// 这个函数是将[first,last)之间的list node 转移到position开始的地方,
//(*(last.node).prev).next=position.node。
//只涉及到指针操作，不涉及任何节点的拷贝创建。
//这个函数涉及6个指针的调整， 
//[first,last)这段的前后指针，
//[first,last)插入到position，4个指针。
  void transfer(iterator position, iterator first, iterator last) {
    if (position != last) {
      (*(link_type((*last.node).prev))).next = position.node;
      (*(link_type((*first.node).prev))).next = last.node;
      (*(link_type((*position.node).prev))).next = first.node;  
      link_type tmp = link_type((*position.node).prev);
      (*position.node).prev = (*last.node).prev;
      (*last.node).prev = (*first.node).prev; 
      (*first.node).prev = tmp;
    }
  }


public:
  //splice 胶接
  void splice(iterator position, list& x) {
    if (!x.empty()) 
      transfer(position, x.begin(), x.end());
  }
  void splice(iterator position, list&, iterator i) {
    iterator j = i;
    ++j;
    if (position == i || position == j) return;
    transfer(position, i, j);
  }
  void splice(iterator position, list&, iterator first, iterator last) {
    if (first != last) 
      transfer(position, first, last);
  }

  //除了常规的插入，删除，
  //list还提供了自己的sort, merge,remove, unique，reverse操作，
  //因为list是操作的指针，而不是元素的拷贝
  void remove(const T& value);
  void unique();
  void merge(list& x);
  void sort();


  template  void remove_if(Predicate);
  template  void unique(BinaryPredicate);
  template  void merge(list&, StrictWeakOrdering);
  template  void sort(StrictWeakOrdering);

  void reverse();

};



