struct __rb_tree_node_base
{
  typedef __rb_tree_color_type color_type;
  typedef __rb_tree_node_base* base_ptr;

  color_type color; 
  base_ptr parent;
  base_ptr left;
  base_ptr right;

  static base_ptr minimum(base_ptr x)
  {
    while (x->left != 0) x = x->left;
    return x;
  }

  static base_ptr maximum(base_ptr x)
  {
    while (x->right != 0) x = x->right;
    return x;
  }
};

template 
struct __rb_tree_node : public __rb_tree_node_base
{
  typedef __rb_tree_node* link_type;
  Value value_field;
};


struct __rb_tree_base_iterator
{
  typedef __rb_tree_node_base::base_ptr base_ptr;
  typedef bidirectional_iterator_tag iterator_category;
  typedef ptrdiff_t difference_type;
  base_ptr node;

  //increment不支持end++
  //decrement不支持begin--
  //begin--,end++都是没有意义的

  //如果当前迭代器就是end(),也就是指向header,那么这个算法是不对的。
  //也就是说，end()++是没有意义的，不支持end()++
  void increment()
  {
    if (node->right != 0) {
      node = node->right;
      while (node->left != 0)
        node = node->left;
    }
    else {
      base_ptr y = node->parent;
      while (node == y->right) {
        node = y;
        y = y->parent;
      }
      //按理说，这里最后直接node=y 即可，为什么要加个if判断呢？
      //如果当前iterator指向root节点，并且root节点是最后一个节点，运行到这里时，node指向header，y指向root, 已经可以了，不能再将node指向root了。
      if (node->right != y)
        node = y;
    }
  }


  void decrement()
  {
    //当前iterator就是end,也就是指向header
    //end--指向最大的节点
    if (node->color == __rb_tree_red &&
        node->parent->parent == node)
      node = node->right;
    else if (node->left != 0) {
      base_ptr y = node->left;
      while (y->right != 0)
        y = y->right;
      node = y;
    }
    else {
      base_ptr y = node->parent;
      while (node == y->left) {
        node = y;
        y = y->parent;
      }
      //如果当前的iterator指向root,并且root是最小的节点，也就是root是begin
      //那么这里为什么不加个if(node->left!=y)的判断呢？
      //因为begin--没有意义，不支持begin--的操作
      node = y;
    }
  }
};

template 
struct __rb_tree_iterator : public __rb_tree_base_iterator
{
  typedef Value value_type;
  typedef Ref reference;
  typedef Ptr pointer;
  typedef __rb_tree_iterator             iterator;
  typedef __rb_tree_iterator const_iterator;
  typedef __rb_tree_iterator                   self;
  typedef __rb_tree_node* link_type;



  __rb_tree_iterator() {}
  __rb_tree_iterator(link_type x) { node = x; }
  __rb_tree_iterator(const iterator& it) { node = it.node; }

  reference operator*() const { return link_type(node)->value_field; }
  pointer operator->() const { return &(operator*()); }

  self& operator++() { increment(); return *this; }
  self operator++(int) {
    self tmp = *this;
    increment();
    return tmp;
  }

  self& operator--() { decrement(); return *this; }
  self operator--(int) {
    self tmp = *this;
    decrement();
    return tmp;
  }
};

inline bool operator==(const __rb_tree_base_iterator& x,
                       const __rb_tree_base_iterator& y) {
  return x.node == y.node;
}

inline bool operator!=(const __rb_tree_base_iterator& x,
                       const __rb_tree_base_iterator& y) {
  return x.node != y.node;
}


