template 
typename rb_tree::link_type 
rb_tree::__copy(link_type x, link_type p) {
                                // structural copy.  x and p must be non-null.
  link_type top = clone_node(x);
  top->parent = p;

  __STL_TRY {
    if (x->right)
      top->right = __copy(right(x), top);
    if (x->left)
      top->left= __copy(left(x), top);
  }
  /*
  //源代码在处理完top->right之后是这样写的， 莫名其妙的不优雅
