template 
typename rb_tree::iterator
rb_tree::insert_equal(const Value& v)
{
  link_type y = header;
  link_type x = root();
  while (x != 0) {
    y = x;
    x = key_compare(KeyOfValue()(v), key(x)) ? left(x) : right(x);
  }
  return __insert(x, y, v);
}


template 
pair::iterator, bool>
rb_tree::insert_unique(const Value& v)
{
  link_type y = header;
  link_type x = root();
  bool comp = true;
  while (x != 0) {
    y = x;
    comp = key_compare(KeyOfValue()(v), key(x));
    x = comp ? left(x) : right(x);
  }
  iterator j = iterator(y);   
  if (comp)
    if (j == begin())     
      return pair(__insert(x, y, v), true);
    else
      --j;
  if (key_compare(key(j.node), KeyOfValue()(v)))
    return pair(__insert(x, y, v), true);
  //如果无法插入，返回的第二个值为false,第一个值为值相同的节点的迭代器
  return pair(j, false);
}





template  template
void rb_tree::insert_equal(II first, II last) {
  for ( ; first != last; ++first)
    insert_equal(*first);
}

template  template
void rb_tree::insert_unique(II first, II last) {
  for ( ; first != last; ++first)
    insert_unique(*first);
}



