typename rb_tree::size_type 
rb_tree::erase(const Key& x) {
  pair p = equal_range(x);
  size_type n = 0;
  distance(p.first, p.second, n);
  erase(p.first, p.second);
  return n;
}


template 
void rb_tree::erase(iterator first, 
                                                            iterator last) {
  if (first == begin() && last == end())
    clear();
  else
    while (first != last) erase(first++);
}

template 
void rb_tree::erase(const Key* first, 
                                                            const Key* last) {
  while (first != last) erase(*first++);
}

//找不到返回end()
//在存在多个key相同的情况下，返回的是最左边的node的迭代器。
template 
typename rb_tree::iterator 
rb_tree::find(const Key& k) {
  link_type y = header;        
  link_type x = root();       

  while (x != 0) 
    if (!key_compare(key(x), k))
      y = x, x = left(x);
    else
      x = right(x);

  iterator j = iterator(y);   
  return (j == end() || key_compare(k, key(j.node))) ? end() : j;
}



template 
typename rb_tree::size_type 
rb_tree::count(const Key& k) const {
  pair p = equal_range(k);
  size_type n = 0;
  distance(p.first, p.second, n);
  return n;
}

//返回第一个大于等于 k 的节点的iterator.
template 
typename rb_tree::iterator 
rb_tree::lower_bound(const Key& k) {
  link_type y = header; 
  link_type x = root(); 

  while (x != 0) 
    if (!key_compare(key(x), k))
      y = x, x = left(x);
    else
      x = right(x);

  return iterator(y);
}


//返回第一个大于 k 的节点的iterator.
template 
typename rb_tree::iterator 
rb_tree::upper_bound(const Key& k) {
  link_type y = header; 
  link_type x = root(); 

   while (x != 0) 
     if (key_compare(k, key(x)))
       y = x, x = left(x);
     else
       x = right(x);

   return iterator(y);
}



template 
inline pair::iterator,
            typename rb_tree::iterator>
rb_tree::equal_range(const Key& k) {
  return pair(lower_bound(k), upper_bound(k));
}

