#include 

void increment(int& x)
{
    x++;
}

int main()
{
    int x = 0;

    std::thread t2(increment, std::ref(x)); // Pass x as reference
    t2.join();
    std::cout 
std::ref返回std::reference_wrapper对象
template 
std::reference_wrapper ref(T& t)
{
    return std::reference_wrapper(t);
}

std::reference_wrapper is a class template that encapsulates a reference in a copy-constructible, assignable object. It is defined in the  header.
Here is a simplified version of how its implementation may look like:
template 
class reference_wrapper {
public:
    typedef T type;

    reference_wrapper(T& ref) noexcept : t_(&ref) {}
    reference_wrapper(const reference_wrapper& x )t_(x.t_){}
    reference_wrapper& operator=(const reference_wrapper& x) noexcept {
        t_ = x.t_;
        return *this;
    }

    operator T& () const noexcept {
        return *t_;
    }

    T& get() const noexcept {
        return *t_;
    }

private:
    T* t_;
};

相应的，还有cref,就是传递const引用的
  template
    reference_wrapper cref(const _Tp& __t) noexcept
    { return reference_wrapper(__t); }

