using std::shared_ptr;

class RuleConfig{
    //...
};

class RuleConfigParser{
//...
public:
    virtual ~RuleConfigParser(){};
    virtual std::shared_ptr parse(const string& ruleCongifText) = 0;
};

class JsonRuleConfigParser : public RuleConfigParser {
public:
    std::shared_ptr parse(const string& ruleCongifText){
        //...解析json文件
        return std::make_shared();
    }
};

class XmlRuleConfigParser : public RuleConfigParser {
public:
    std::shared_ptr parse(const string& ruleCongifText){
        //...解析xml文件
        return std::make_shared();
    }
};


class SystemConfig{
    //...
};


class SystemConfigParser{
//...
public:
    virtual ~SystemConfigParser(){};
    virtual std::shared_ptr parse(const string& systemCongifText) = 0;
};

class JsonSystemConfigParser : public SystemConfigParser {
public:
    std::shared_ptr parse(const string& systemCongifText){
