class ConfigParserFactory {
public:
  virtual ~ConfigParserFactory();
  virtual shared_ptr createRuleParser() =0;
  virtual shared_ptr createSystemParser() =0;
  //此处可以扩展新的parser类型，比如BizConfigParser
};

class JsonConfigParserFactory : public  ConfigParserFactory {
public: 
  shared_ptr createRuleParser(){
    return std::make_shared();
  }

  shared_ptr createSystemParser(){
    return std::make_shared();
  }
};

class XmlConfigParserFactory : public  ConfigParserFactory {
public: 
  shared_ptr createRuleParser(){
    return std::make_shared();
  }

  shared_ptr createSystemParser(){
    return std::make_shared();
  }
};


class ConfigSource {
public:
    std::shared_ptr loadRuleConfig(const string &  ruleConfigFilePath) {
        std::shared_ptr ruleConfig;
        string ruleConfigFileExtension = getFileExtension(ruleConfigFilePath);
        std::shared_ptr parserFactory;
        if (ruleConfigFileExtension=="json") {
            parserFactory.reset(new JsonConfigParserFactory());
        } else if (ruleConfigFileExtension=="xml") {
            parserFactory.reset(new XmlConfigParserFactory());
        } 
        if(parserFactory!=nullptr){
            std::shared_ptr parser  = parserFactory->createRuleParser();
