    if(name.empty()){
        throw std::invalid_argument("invalid name");
    }
    _name = name;
    if(maxTotal  MAX_MAX_TOTAL ){
        throw std::invalid_argument("invalid maxTotal ");
    }
    _maxTotal=maxTotal;
    if(maxIdle maxTotal){
        throw std::invalid_argument("invalid maxIdle ");
    }
    _maxIdle=maxIdle;
    if(minIdle  maxIdle ){
        throw std::invalid_argument("invalid minIdle ");
    }
    _minIdle=minIdle;
  }

private:
  const static int DEFAULT_MAX_TOTAL = 8;
  const static int MAX_MAX_TOTAL = 16;
  const static int DEFAULT_MAX_IDLE = 8;
  const static int DEFAULT_MIN_IDLE = 0;

  string _name;
  int _maxTotal;
  int _maxIdle;
  int _minIdle;
};

这里的参数数量较少，依赖关系也比较简单。如果后续又多了别的参数，参数之间的依赖关系更复杂。则构造函数的内部逻辑会更为复杂，而且使用起来也不方便。这时候就可以用建设者模式来优化。
