posts/c&c++/设计模式/结构型/05 代理模式.html.body:
代理模式有原始类和代理类。在不改变原始类（或叫被代理类）的情况下，通过引入代理类来给原始类附加功能。
代理模式常用在业务系统中开发一些非功能性需求，比如：监控、统计、鉴权、限流、事务、幂等、日志。我们将这些附加功能与业务功能解耦，放到代理类统一处理，让程序员只需要关注业务方面的开发。
假设我们需要收集以下用户登录接口，注册接口的请求数据，比如访问时间、处理时长等
class IUserController{
public:
  virtual ~IUserController(){}
  virtual std::shared_ptr login(string telephone,string password) =0;
  virtual std::shared_ptr reg(string telephone, string password) =0;
};

class UserController : public IUserController {
public:
  std::shared_ptr login(string telephone,string password){
    //...
    return std::make_shared();
  }
  std::shared_ptr reg(string telephone, string password) {
    //...
    return std::make_shared();
  }
};

我们提供代理类UserControllerProxy，将与具体业务无关的逻辑放到代理类中
class UserControllerProxy: public  IUserController {
public:
  UserControllerProxy( shared_ptr controller, shared_ptr collector ):userController(controller),metricsCollector(collector){}

  std::shared_ptr login(string telephone,string password){
    auto starttime = std::chrono::duration_cast(std::chrono::system_clock::now().time_since_epoch()).count();

    auto res = userController->login(telephone,password);

    auto endtime = std::chrono::duration_cast(std::chrono::system_clock::now().time_since_epoch()).count();
    metricsCollector->collect("login",starttime,endtime-starttime);
    return res;
  }
  std::shared_ptr reg(string telephone, string password) {
    auto starttime = std::chrono::duration_cast(std::chrono::system_clock::now().time_since_epoch()).count();

    auto res = userController->reg(telephone,password);

    auto endtime = std::chrono::duration_cast(std::chrono::system_clock::now().time_since_epoch()).count();
    metricsCollector->collect("register",starttime,endtime-starttime);
    return res;
  }
private:
  shared_ptr metricsCollector;
  shared_ptr userController;
};

其使用如下
int main(){
    std::shared_ptr userController = std::make_shared(std::make_shared(),std::make_shared());
    userController->login("12345","admin");
};

