posts/c&c++/设计模式/结构型/06 装饰器模式.html.body:
装饰器模式和代理模式很像,如下

// 代理模式的代码结构
class  IA {
public:
  virtual ~IA(){};
  virtual void f() =0;
};
class A : public  IA {
public:
  void f() {
    //..
  };
};
class AProxy : public IA {
public:
  AProxy(shared_ptr _a):a{_a}{}
  void f() {
    // 新添加的代理逻辑
    a->f();
    // 新添加的代理逻辑
  }
private:
  shared_ptr a;
};


// 装饰器模式的代码结构
class IA {
public:
  virtual ~IA(){};
  virtual void f() =0;
};

class A : public  IA {
public:
  void f() {
    //..
  };
};

class AProxy : public IA {
public:
  AProxy(shared_ptr _a):a{_a}{}
  void f() {
    // 功能增强代码
    a->f();
    // 功能增强代码
  }
private:
  shared_ptr a;
};

主要区别在于代理模式增加的是业务无关的代码。而装饰器模式增加的功能增强的代码。
比如java的IO库
InputStream in = new FileInputStream("/user/wangzheng/test.txt");
InputStream bin = new BufferedInputStream(in);
DataInputStream din = new DataInputStream(bin);
int data = din.readInt();

FileInputStream，BufferedInputStream，DataInputStream都是抽象类InputStream的实现。BufferedInputStream，DataInputStream是装饰器类。
BufferedInputStream给InputStream增加了缓存功能，DataInputStream又给InputStream增加了基本数据类型读取的功能。
如果通过继承的方式实现功能增强，给FileInputStream派生出BufferedFileInputStream,DataFileInputStream,BufferedDataFileInputStream…………会有继承层次过深过复杂的问题。更何况InputStream还有别的子类
本质上是组合优于继承的设计思想。
一个简单的c++的例子
#include 
#include 
#include 

// Component Interface
class TextProcessor {
public:
    virtual ~TextProcessor() = default;
    virtual std::string process(const std::string& input) const = 0;
};

// Concrete Component
class PlainTextProcessor : public TextProcessor {
public:
    std::string process(const std::string& input) const override {
        return input;
    }
};

// Decorator
//这个Decorator基类主要是提取不同Decorator的共同代码，避免代码重复
class TextDecorator : public TextProcessor {
protected:
    std::shared_ptr component;
public:
    explicit TextDecorator(std::shared_ptr comp) : component(comp) {}
    std::string process(const std::string& input) const override {
        return component->process(input);
    }
};

// Concrete Decorators
class UpperCaseDecorator : public TextDecorator {
public:
    explicit UpperCaseDecorator(std::shared_ptr comp) : TextDecorator(comp) {}
    std::string process(const std::string& input) const override {
        std::string result = component->process(input);
        for (auto& ch : result) ch = toupper(ch);
        return result;
    }
};

class AddPrefixDecorator : public TextDecorator {
    std::string prefix;
public:
    AddPrefixDecorator(std::shared_ptr comp, const std::string& pref)
        : TextDecorator(comp), prefix(pref) {}
    std::string process(const std::string& input) const override {
        return prefix + component->process(input);
    }
};

// Usage
int main() {
    // Create the base component
    auto processor = std::make_shared();

    // Add decorators dynamically
    auto upperCaseProcessor = std::make_shared(processor);
    auto prefixedProcessor = std::make_shared(upperCaseProcessor, "[Prefix]: ");

    std::string input = "Hello, Decorator Pattern!";
    std::cout process(input) process(input) process(input) 
