Strategy Design Pattern : Define a family of algorithms, encapsulate each one, and make them interchangeable. Strategy lets the algorithm vary independently from clients that use it.
假设订单服务有根据订单类型计算折扣的接口，如下
enum class OrderType{
    NORMAL,GROUPON,PROMOTION
};

class Order{
//...
public:
  OrderType getType() const ;
};

class OrderService {
//...
public:
  //...
  double discount(const Order &  order) {
    double discount = 0.0;
    OrderType type = order.getType();
    if (type == OrderType::NORMAL) { // 普通订单
      //...省略折扣计算算法代码
    } else if (type == OrderType::GROUPON) { // 团购订单
      //...省略折扣计算算法代码
    } else if (type==OrderType::PROMOTION) { // 促销订单
      //...省略折扣计算算法代码
    }
    return discount;
  }
};

使用策略模式重构后
#include 
#include 

using std::map;
using std::shared_ptr;

enum class OrderType{
    NORMAL,GROUPON,PROMOTION
};

class Order{
//...
public:
  OrderType getType() const ;
};

// 策略的定义
class  DiscountStrategy {
public:
  virtual ~DiscountStrategy(){};
  virtual double calDiscount(const Order & order) =0;
};

class NormalDiscountStrategy: public DiscountStrategy{
public:
  double calDiscount(const Order & order){
    //...
  }
};

class GrouponDiscountStrategy: public DiscountStrategy{
public:
  double calDiscount(const Order & order){
    //...
  }
};

class PromotionDiscountStrategy: public DiscountStrategy{
public:
  double calDiscount(const Order & order){
    //...
  }
};


// 策略的创建
class DiscountStrategyFactory {
public:
  static shared_ptr getDiscountStrategy(const OrderType&  type) {
    return strategies[type];
  }

private:
  static map> strategies;
};

 map> DiscountStrategyFactory::strategies = {
    {OrderType::NORMAL, shared_ptr(new NormalDiscountStrategy())},
    {OrderType::GROUPON, shared_ptr(new GrouponDiscountStrategy())},
    {OrderType::PROMOTION, shared_ptr(new PromotionDiscountStrategy())}
 };



// 策略的使用
class OrderService {
public:
  double discount(const Order& order) {
    OrderType type = order.getType();
    shared_ptr discountStrategy = DiscountStrategyFactory::getDiscountStrategy(type);
    return discountStrategy->calDiscount(order);
  }
};

一般来讲，如果策略类是无状态的，不包含成员变量，只是纯粹的算法实现，这样的策略对象是可以被共享使用的，这时候，我们可以使用上面这种工厂类的实现方式，事先创建好每个策略对象，缓存到工厂类中，用的时候直接返回。
相反，如果策略类是有状态的，根据业务场景的需要，我们希望每次从工厂方法中，获得的都是新创建的策略对象，而不是缓存好可共享的策略对象，那我们就需要按照如下方式来实现策略工厂类。
// 策略的创建
class DiscountStrategyFactory {
public:
  static shared_ptr getDiscountStrategy(const OrderType& type) {
    shared_ptr strategy;
    if(type==OrderType::NORMAL){
        strategy.reset(new NormalDiscountStrategy() );
    }else if (type == OrderType::GROUPON){
        strategy.reset(new GrouponDiscountStrategy() );
    }else if (type == OrderType::PROMOTION){
        strategy.reset(new PromotionDiscountStrategy());
    }
    return strategy;
  }
};

